"use client";

import { loadFont } from "@remotion/google-fonts/Lexend";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_LEAD,
  splitWords,
  type YourNameHereElementId,
  yourNameHereTimeline,
} from "./timeline";

const lexend = loadFont("normal", {
  weights: ["300", "400", "500"],
  subsets: ["latin"],
});

export interface YourNameHereProps {
  lead?: string;
  brand?: string;
  slot?: string;
  end?: string;
  note?: string;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Lexend by default. */
  fontFamily?: string;
  /** Frames between words as the lead builds. */
  stagger?: number;
  /** Size of the text, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single lead words, the brand line, the braces,
   * the swap, the opening and the note, by the ids in `./timeline`. Frames on
   * the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<YourNameHereElementId>;
}

const THEMES = {
  dark: { bg: "#E8392B", ink: "#FFFFFF", accent: "#0A0A0A" },
  light: { bg: "#FFFFFF", ink: "#0A0A0A", accent: "#E8392B" },
} as const;

const TRACK = -0.04;
const NOTE_TRACK = -0.01;
const LH = 1.02;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Spec {
  text: string;
  weight: number;
}

function useWidths(specs: Spec[], fontFamily: string) {
  const key = `${fontFamily}\u0002${specs.map((s) => `${s.weight}|${s.text}`).join("\u0001")}`;
  const [state, setState] = useState<{
    key: string;
    w: Record<string, number>;
  } | null>(null);
  const [handle] = useState(() => delayRender("your-name-here: measuring"));
  const released = useRef(false);
  const ref = useRef(specs);
  ref.current = specs;
  useEffect(() => {
    let live = true;
    const weights = Array.from(new Set(ref.current.map((s) => s.weight)));
    Promise.all([
      lexend.waitUntilDone(),
      ...weights.map((wt) =>
        document.fonts.load(`${wt} 100px "${fontFamily}"`),
      ),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        const ctx = document.createElement("canvas").getContext("2d");
        const w: Record<string, number> = {};
        for (const s of ref.current) {
          const k = `${s.weight}|${s.text}`;
          if (ctx) {
            ctx.font = `${s.weight} 100px "${fontFamily}"`;
            w[k] = ctx.measureText(s.text).width / 100;
          } else {
            w[k] = s.text.length * 0.56;
          }
        }
        setState({ key, w });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, fontFamily]);
  return state && state.key === key ? state.w : null;
}

function greedy(
  words: string[],
  adv: (s: string) => number,
  space: number,
  maxEm: number,
) {
  const lines: string[][] = [];
  let line: string[] = [];
  let x = 0;
  for (const word of words) {
    const w = adv(word);
    if (line.length > 0 && x + space + w > maxEm) {
      lines.push(line);
      line = [word];
      x = w;
    } else {
      x += (line.length > 0 ? space : 0) + w;
      line.push(word);
    }
  }
  if (line.length > 0) lines.push(line);
  return lines;
}

function balanced(
  words: string[],
  adv: (s: string) => number,
  space: number,
  maxEm: number,
) {
  const base = greedy(words, adv, space, maxEm);
  if (base.length <= 1) return base;
  let lo = 0;
  let hi = maxEm;
  for (let k = 0; k < 24; k++) {
    const mid = (lo + hi) / 2;
    if (greedy(words, adv, space, mid).length <= base.length) hi = mid;
    else lo = mid;
  }
  return greedy(words, adv, space, hi);
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function YourNameHere(props: YourNameHereProps) {
  const {
    lead = DEFAULT_LEAD,
    brand = "remocn",
    slot = "yourProduct",
    end = ".",
    note = "Swap one prop. The film is yours.",
    accent,
    ink,
    background,
    fontFamily = lexend.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  // The pace is counted on the clip after the delay, with `speed`.
  const Tt = Math.max(0, durationInFrames - delay) * speed;
  const tl = useTimeline(yourNameHereTimeline, props, Tt, timing);
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const hi = accent ?? c.accent;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);

  const leadWords = splitWords(lead);
  const w = useWidths(
    [
      { text: " ", weight: 500 },
      ...leadWords.map((text) => ({ text, weight: 500 })),
      { text: brand, weight: 500 },
      { text: slot, weight: 500 },
      { text: "{", weight: 400 },
      { text: "}", weight: 400 },
      { text: end, weight: 500 },
      { text: note, weight: 300 },
    ],
    fontFamily,
  );

  if (!w) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const adv = (s: string, wt = 500) =>
    s ? (w[`${wt}|${s}`] ?? s.length * 0.56) + TRACK * Array.from(s).length : 0;
  const space = w["500| "] ?? 0.25;
  const bw = adv("{", 400) + 0.02;
  const cw = adv("}", 400) + 0.02;
  const brandW = adv(brand);
  const slotW = adv(slot);
  const endW = adv(end);
  const slotLineEm = Math.max(bw + brandW + cw, bw + slotW + cw) + endW;

  const portrait = H > W * 1.1;
  const mx = W * (portrait ? 0.07 : 0.065);
  const availW = W - mx * 2;
  let fs = Math.min(portrait ? W * 0.2 : H * 0.24, availW / slotLineEm);
  let leadLines = balanced(leadWords, adv, space, availW / fs);
  const fN0 = portrait ? W * 0.045 : H * 0.045;
  const noteEm =
    (w[`300|${note}`] ?? note.length * 0.56) +
    NOTE_TRACK * Array.from(note).length;
  const fN = note ? Math.min(fN0, availW / Math.max(0.01, noteEm)) : 0;
  const totalH = () =>
    (leadLines.length + 1) * LH * fs + (note ? fs * 0.34 + fN * 1.3 : 0);
  for (let k = 0; k < 80; k++) {
    if (
      leadLines.length <= (portrait ? 4 : 3) &&
      totalH() <= H * (portrait ? 0.7 : 0.84)
    )
      break;
    fs *= 0.96;
    leadLines = balanced(leadWords, adv, space, availW / fs);
  }

  const lineH = LH * fs;
  const blockTop = (H - totalH()) / 2 - H * (portrait ? 0.02 : 0.01);
  const slotTop = blockTop + leadLines.length * lineH;
  const noteTop = slotTop + lineH + fs * 0.34;

  const brace = tl.get("brace");
  const swap = tl.get("swap");
  const openEl = tl.get("open");
  const noteEl = tl.get("note");
  const swapAt = swap.start;
  const openAt = openEl.start;

  const p1 = interpolate(t, [brace.start, brace.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const out = interpolate(t, [swapAt, swapAt + swap.beat("out")], [0, 1], {
    ...CLAMP,
    easing: EASE_IN,
  });
  const shut = interpolate(t, [swapAt + swap.beat("shut"), swap.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const open = interpolate(t, [openAt, openAt + openEl.beat("open")], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const rise = interpolate(
    t,
    [openAt + openEl.beat("rise"), openEl.end],
    [0, 1],
    { ...CLAMP, easing: EASE_OUT },
  );
  const noteE = interpolate(t, [noteEl.start, noteEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const gapW = 0.42;
  const inner = brandW + (gapW - brandW) * shut + (slotW - gapW) * open;
  const brandX = bw * p1;
  const closeX = bw * p1 + inner;
  const endX = bw * p1 + inner + cw * p1;

  let wordIndex = 0;
  const leadNodes = leadLines.map((line, li) => (
    <div
      key={`l${li}`}
      style={{
        position: "absolute",
        left: mx,
        top: blockTop + li * lineH,
        height: lineH,
        lineHeight: `${lineH}px`,
        fontSize: fs,
        fontWeight: 500,
        whiteSpace: "pre",
        letterSpacing: `${TRACK}em`,
        color: fg,
      }}
    >
      {line.map((word, wi) => {
        const wordEl = tl.get(`word:${wordIndex}`);
        wordIndex++;
        const e = interpolate(t, [wordEl.start, wordEl.end], [0, 1], {
          ...CLAMP,
          easing: EASE_OUT,
        });
        return (
          <span key={`lw${wi}`}>
            {wi > 0 ? " " : ""}
            <span
              style={{
                display: "inline-block",
                opacity: e,
                transform: `translateY(${((1 - e) * fs * 0.28).toFixed(2)}px)${glide(midway(e))}`,
              }}
            >
              {word}
            </span>
          </span>
        );
      })}
    </div>
  ));

  const brandEl = tl.get("brand");
  const brandIn = interpolate(t, [brandEl.start, brandEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const glyph = (
    text: string,
    x: number,
    extra: React.CSSProperties,
  ): React.ReactNode => (
    <div
      style={{
        position: "absolute",
        left: x * fs,
        top: 0,
        height: lineH,
        lineHeight: `${lineH}px`,
        whiteSpace: "pre",
        ...extra,
      }}
    >
      {text}
    </div>
  );

  const clipPad = fs * 0.08;

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily,
      }}
    >
      <ScaleLayer scale={scale}>
        {leadNodes}
        <div
          style={{
            position: "absolute",
            left: mx,
            top: slotTop,
            height: lineH,
            width: availW,
            fontSize: fs,
            fontWeight: 500,
            letterSpacing: `${TRACK}em`,
            opacity: brandIn,
            transform: `translateY(${((1 - brandIn) * fs * 0.28).toFixed(2)}px)${glide(midway(brandIn))}`,
          }}
        >
          {glyph("{", 0, {
            color: hi,
            fontWeight: 400,
            opacity: p1,
            transform: `translateX(${((1 - p1) * fs * 0.25).toFixed(2)}px)`,
          })}
          <div
            style={{
              position: "absolute",
              left: brandX * fs,
              top: -clipPad,
              width: (inner + 0.03) * fs,
              height: lineH + clipPad + fs * 0.14,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                position: "absolute",
                left: 0,
                // Both words travel by transform, not `top`: layout rounds a
                // baseline to whole pixels, so a word eased by `top` clicks.
                top: clipPad,
                transform:
                  out > 0
                    ? `translateY(${out * fs * 0.55}px)${glide(midway(out))}`
                    : undefined,
                height: lineH,
                lineHeight: `${lineH}px`,
                whiteSpace: "pre",
                color: fg,
                opacity: 1 - out,
              }}
            >
              {brand}
            </div>
            <div
              style={{
                position: "absolute",
                left: 0,
                top: clipPad,
                transform:
                  rise < 1
                    ? `translateY(${(1 - rise) * fs * 0.45}px)${glide(midway(rise))}`
                    : undefined,
                height: lineH,
                lineHeight: `${lineH}px`,
                whiteSpace: "pre",
                color: hi,
                opacity: rise,
              }}
            >
              {slot}
            </div>
          </div>
          {glyph("}", closeX, {
            color: hi,
            fontWeight: 400,
            opacity: p1,
            transform: `translateX(${((1 - p1) * -fs * 0.25).toFixed(2)}px)`,
          })}
          {glyph(end, endX, { color: fg })}
        </div>
        {note ? (
          <div
            style={{
              position: "absolute",
              left: mx,
              top: noteTop,
              fontSize: fN,
              lineHeight: `${fN * 1.3}px`,
              fontWeight: 300,
              whiteSpace: "pre",
              letterSpacing: `${NOTE_TRACK}em`,
              color: fg,
              opacity: noteE,
              transform: `translateY(${((1 - noteE) * fN * 0.6).toFixed(2)}px)${glide(midway(noteE))}`,
            }}
          >
            {note}
          </div>
        ) : null}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The lead rising in word by word, the brand line under it, the braces
// opening around the brand, the brand dropping out as the slot shuts, the
// slot opening on the placeholder, and the note. Frames on the 30 fps scene
// timeline, after `delay` and `speed`. On a longer or shorter clip the braces
// and the swap come later or sooner (`pace`, 0.85–1.5). The ids are public: a
// saved `timing` prop refers to them.

export type YourNameHereElementId =
  | `word:${number}`
  | "brand"
  | "brace"
  | "swap"
  | "open"
  | "note";

export interface YourNameHereTimingProps {
  lead?: string;
  stagger?: number;
}

export const DEFAULT_LEAD = "A launch film for";
export const WORD_STAGGER = 3;

const WORDS_AT = 3;
const WORD_RISE = 18;
const BRAND_GAP = 2;
const BRAND_RISE = 20;
const BRACE_AT = 44;
const BRACE_LEN = 16;
const SWAP_GAP = 26;
const OUT_LEN = 12;
const SHUT_AT = 4;
const SWAP_LEN = 18;
const OPEN_GAP = 28;
const OPEN_LEN = 20;
const RISE_AT = 4;
const RISE_END = 22;
const NOTE_GAP = 30;
const NOTE_LEN = 18;

export const splitWords = (s: string) => s.split(/\s+/).filter(Boolean);

// `word:<i>` is word `i` of the lead, a chain; the brand line follows the
// last word. The braces open on a clock of their own; the swap follows them:
// the brand drops out over `out` while the slot shuts from `shut` to the
// swap's end. `open` follows the swap: the slot widens over `open` and the
// placeholder rises from `rise` to its end. The note follows the opening.
// `length` is the clip after `delay`, with `speed`.
export const yourNameHereTimeline = defineTimeline<
  YourNameHereElementId,
  YourNameHereTimingProps
>(({ lead = DEFAULT_LEAD, stagger = WORD_STAGGER }, { length }) => {
  const words = splitWords(lead);
  const n = words.length;
  const pace = Math.min(1.5, Math.max(0.85, length / 180));
  const braceAt = BRACE_AT * pace;
  const swapAt = braceAt + SWAP_GAP * pace;
  const openAt = swapAt + OPEN_GAP;
  const noteAt = openAt + NOTE_GAP;
  const elements: TimelineElement<YourNameHereElementId>[] = words.map(
    (word, i): TimelineElement<YourNameHereElementId> => ({
      id: `word:${i}`,
      lane: "Lead",
      label: word,
      start: WORDS_AT + i * stagger,
      length: WORD_RISE,
      follows: i > 0 ? `word:${i - 1}` : undefined,
    }),
  );
  elements.push(
    {
      id: "brand",
      lane: "Slot",
      label: "brand",
      start: WORDS_AT + n * stagger + BRAND_GAP,
      length: BRAND_RISE,
      follows: n > 0 ? `word:${n - 1}` : undefined,
    },
    {
      id: "brace",
      lane: "Slot",
      label: "braces",
      start: braceAt,
      length: BRACE_LEN,
    },
    {
      id: "swap",
      lane: "Slot",
      label: "swap",
      start: swapAt,
      length: SWAP_LEN,
      follows: "brace",
      beats: { out: OUT_LEN, shut: SHUT_AT },
    },
    {
      id: "open",
      lane: "Slot",
      label: "open",
      start: openAt,
      length: RISE_END,
      follows: "swap",
      beats: { open: OPEN_LEN, rise: RISE_AT },
    },
    {
      id: "note",
      lane: "Note",
      label: "note",
      start: noteAt,
      length: NOTE_LEN,
      follows: "open",
    },
  );
  return elements.sort((a, b) => a.start - b.start);
});
